# -*- coding: utf-8 -*-
SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">ORGANİK KİMYANIN TARİHÇESİ (WÖHLER SENTEZİ) VE KARŞILAŞTIRMA (12.2.1.1)</text>\n  <rect x="20" y="44" width="660" height="60" rx="8" fill="#fef3c7" stroke="#d97706" stroke-width="2"/>\n  <text x="350" y="64" text-anchor="middle" font-size="12" font-weight="bold" fill="#92400e">Vitalizm (Yaşam Gücü) Görüşünün Yıkılması — Friedrich Wöhler (1828)</text>\n  <text x="350" y="84" text-anchor="middle" font-size="11" font-weight="bold" fill="#78350f">Pb(OCN)₂ + 2NH₃ + 2H₂O → 2NH₄OCN (Anorganik Amonyum Siyanat) —(Isı)→ (NH₂)₂CO (Organik Üre)</text>\n  <text x="350" y="98" text-anchor="middle" font-size="10" fill="#b45309">Laboratuvarda anorganik maddeden sentezlenen ilk organik bileşik ÜRE\'dir!</text>\n  <rect x="20" y="114" width="320" height="130" rx="10" fill="#dcfce7" stroke="#16a34a" stroke-width="2"/>\n  <text x="180" y="134" text-anchor="middle" font-size="12" font-weight="bold" fill="#166534">Organik Bileşiklerin Özellikleri</text>\n  <text x="32" y="154" font-size="10.5" fill="#14532d">• Temel elementi <tspan font-weight="bold">C (karbon)</tspan> olup yanında H, O, N, S, P, X bulunur.</text>\n  <text x="32" y="171" font-size="10.5" fill="#14532d">• Genellikle <tspan font-weight="bold">kovalent</tspan> yapılıdır; erime ve kaynama noktaları düşüktür.</text>\n  <text x="32" y="188" font-size="10.5" fill="#14532d">• Tepkimeleri genellikle <tspan font-weight="bold">yavaştır</tspan>, yanıcıdır ve kendine has kokuları vardır.</text>\n  <text x="32" y="205" font-size="10.5" fill="#14532d">• Karbonun bağ yapma yeteneği ve izomerlik nedeniyle sayıları milyonlarcadır.</text>\n  <text x="32" y="222" font-size="10.5" font-weight="bold" fill="#15803d">• Örnek: CH₄, C₂H₅OH, CH₃COOH, C₆H₁₂O₆, (NH₂)₂CO, CCl₄</text>\n  <rect x="360" y="114" width="320" height="130" rx="10" fill="#dbeafe" stroke="#2563eb" stroke-width="2"/>\n  <text x="520" y="134" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e40af">Anorganik Bileşikler ve Önemli İstisnalar</text>\n  <text x="372" y="154" font-size="10.5" fill="#1e3a8a">• Genellikle <tspan font-weight="bold">iyonik</tspan> yapılıdır; erime-kaynama noktaları yüksektir.</text>\n  <text x="372" y="171" font-size="10.5" fill="#1e3a8a">• Suda iyi çözünür ve sulu çözeltileri elektriği iletir; yanıcı değildir.</text>\n  <rect x="372" y="182" width="296" height="52" rx="6" fill="#fef2f2" stroke="#dc2626"/>\n  <text x="520" y="198" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#991b1b">DİKKAT: Yapısında C Bulunduğu Hâlde ANORGANİK Olanlar!</text>\n  <text x="520" y="213" text-anchor="middle" font-size="10" font-weight="bold" fill="#b91c1c">CO, CO₂, CS₂, HCN, H₂CO₃, Karbonatlar (CO₃²⁻: CaCO₃, Na₂CO₃),</text>\n  <text x="520" y="227" text-anchor="middle" font-size="10" font-weight="bold" fill="#b91c1c">Bikarbonatlar (HCO₃⁻), Karbürler (CaC₂, Al₄C₃) ve Siyanürler (CN⁻)</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">BASİT (KABA) FORMÜL VE MOLEKÜL (GERÇEK) FORMÜLÜ HESAPLAMALARI (12.2.2.1)</text>\n  <rect x="20" y="46" width="320" height="194" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="180" y="68" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1e40af">Basit Formül ve Molekül Formülü İlişkisi</text>\n  <rect x="34" y="80" width="292" height="50" rx="6" fill="#ffffff" stroke="#60a5fa"/>\n  <text x="180" y="98" text-anchor="middle" font-size="11" font-weight="bold" fill="#1d4ed8">Basit (Kaba / Ampirik) Formül:</text>\n  <text x="180" y="116" text-anchor="middle" font-size="10" fill="#1e3a8a">Elementlerin türünü ve en sade tam sayılı mol oranını gösterir.</text>\n  <rect x="34" y="136" width="292" height="50" rx="6" fill="#ffffff" stroke="#60a5fa"/>\n  <text x="180" y="154" text-anchor="middle" font-size="11" font-weight="bold" fill="#1d4ed8">Molekül (Gerçek) Formülü:</text>\n  <text x="180" y="172" text-anchor="middle" font-size="10" fill="#1e3a8a">Bir moleküldeki atomların gerçek sayılarını gösterir.</text>\n  <rect x="34" y="192" width="292" height="36" rx="6" fill="#dbeafe" stroke="#2563eb"/>\n  <text x="180" y="214" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e40af">(Basit Formül) · n = Molekül Formülü   [M_A = n · M_basit]</text>\n  <rect x="360" y="46" width="320" height="194" rx="10" fill="#fae8ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="520" y="68" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#6b21a8">Örnek Karşılaştırma Tablosu</text>\n  <text x="375" y="94" font-size="11" font-weight="bold" fill="#581c87">Bileşik Adı</text>\n  <text x="505" y="94" font-size="11" font-weight="bold" fill="#581c87">Molekül F.</text>\n  <text x="595" y="94" font-size="11" font-weight="bold" fill="#581c87">Basit F. (n)</text>\n  <line x1="372" y1="102" x2="668" y2="102" stroke="#c084fc" stroke-width="1.5"/>\n  <text x="375" y="122" font-size="10.5" fill="#581c87">Glikoz</text>\n  <text x="515" y="122" font-size="10.5" font-weight="bold" fill="#7e22ce">C₆H₁₂O₆</text>\n  <text x="600" y="122" font-size="10.5" fill="#581c87">CH₂O (n = 6)</text>\n  <text x="375" y="145" font-size="10.5" fill="#581c87">Asetik asit</text>\n  <text x="515" y="145" font-size="10.5" font-weight="bold" fill="#7e22ce">C₂H₄O₂</text>\n  <text x="600" y="145" font-size="10.5" fill="#581c87">CH₂O (n = 2)</text>\n  <text x="375" y="168" font-size="10.5" fill="#581c87">Formaldehit</text>\n  <text x="515" y="168" font-size="10.5" font-weight="bold" fill="#7e22ce">CH₂O</text>\n  <text x="600" y="168" font-size="10.5" fill="#581c87">CH₂O (n = 1)</text>\n  <text x="375" y="191" font-size="10.5" fill="#581c87">Benzen / Asetilen</text>\n  <text x="505" y="191" font-size="10.5" font-weight="bold" fill="#7e22ce">C₆H₆ / C₂H₂</text>\n  <text x="600" y="191" font-size="10.5" fill="#581c87">CH (n = 6 / 2)</text>\n  <text x="520" y="222" text-anchor="middle" font-size="10" font-weight="bold" fill="#6b21a8">Basit formülü aynı olanların kütlece % bileşimleri aynıdır!</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">ELEMENTEL ANALİZ (YANMA TEPKİMESİ) İLE FORMÜL BULMA ADIMLARI</text>\n  <rect x="20" y="48" width="205" height="190" rx="10" fill="#fef3c7" stroke="#d97706" stroke-width="2"/>\n  <text x="122" y="70" text-anchor="middle" font-size="12" font-weight="bold" fill="#92400e">1. C ve H Molünü Bulma</text>\n  <text x="32" y="95" font-size="10.5" fill="#78350f">Organik bileşik O₂ ile</text>\n  <text x="32" y="110" font-size="10.5" fill="#78350f">yakıldığında:</text>\n  <text x="32" y="132" font-size="10.5" font-weight="bold" fill="#b45309">• n_C = n_(CO₂)</text>\n  <text x="40" y="147" font-size="10" fill="#78350f">(m_C = n_C · 12 g)</text>\n  <text x="32" y="170" font-size="10.5" font-weight="bold" fill="#b45309">• n_H = 2 · n_(H₂O)</text>\n  <text x="40" y="185" font-size="10" fill="#78350f">(m_H = n_H · 1 g)</text>\n  <text x="32" y="210" font-size="10" fill="#92400e">1 mol H₂O\'da 2 mol H vardır!</text>\n  <rect x="247" y="48" width="205" height="190" rx="10" fill="#dcfce7" stroke="#16a34a" stroke-width="2"/>\n  <text x="350" y="70" text-anchor="middle" font-size="12" font-weight="bold" fill="#166534">2. Oksijen Kontrolü</text>\n  <text x="259" y="95" font-size="10.5" fill="#14532d">Bileşiğin toplam kütlesi</text>\n  <text x="259" y="110" font-size="10.5" fill="#14532d">(m_toplam) ile karşılaştırılır:</text>\n  <text x="259" y="132" font-size="10.5" font-weight="bold" fill="#15803d">• m_C + m_H = m_toplam ise:</text>\n  <text x="267" y="147" font-size="10" fill="#14532d">Bileşik yalnız C ve H içerir</text>\n  <text x="267" y="162" font-size="10" font-weight="bold" fill="#166534">(Hidrokarbondur: C_xH_y).</text>\n  <text x="259" y="184" font-size="10.5" font-weight="bold" fill="#15803d">• m_C + m_H &lt; m_toplam ise:</text>\n  <text x="267" y="199" font-size="10" fill="#14532d">Fark oksijen kütlesidir:</text>\n  <text x="267" y="214" font-size="10" font-weight="bold" fill="#166534">n_O = m_O / 16</text>\n  <rect x="475" y="48" width="205" height="190" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="577" y="70" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e40af">3. Tam Sayıya Çevirme</text>\n  <text x="487" y="95" font-size="10.5" fill="#1e3a8a">• Bulunan n_C : n_H : n_O</text>\n  <text x="495" y="110" font-size="10.5" fill="#1e3a8a">mol sayıları en küçük</text>\n  <text x="495" y="125" font-size="10.5" fill="#1e3a8a">sayıya bölünerek en sade</text>\n  <text x="495" y="140" font-size="10.5" font-weight="bold" fill="#1d4ed8">Basit Formül bulunur.</text>\n  <text x="487" y="165" font-size="10.5" fill="#1e3a8a">• Ardından mol kütlesi (M_A)</text>\n  <text x="495" y="180" font-size="10.5" fill="#1e3a8a">kullanılarak n katsayısı ile</text>\n  <text x="495" y="195" font-size="10.5" font-weight="bold" fill="#1e40af">Molekül Formülü elde edilir.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get('bolumler', [])):
        if i < len(SVGS):
            b['gorsel'] = SVGS[i]
